module barcode_solver(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [1:0] row0_g1, row0_g2,\n    input wire [1:0] row1_g1, row1_g2,\n    input wire [1:0] col0_g1, col0_g2,\n    input wire [1:0] col1_g1, col1_g2,\n    output reg [2:0] row0_vbars,\n    output reg [2:0] row1_vbars,\n    output reg [2:0] col0_hbars,\n    output reg [2:0] col1_hbars,\n    output reg done\n);\n\n    // State definitions\n    localparam [1:0] IDLE = 2'b00;\n    localparam [1:0] SEARCH = 2'b01;\n    localparam [1:0] DONE_STATE = 2'b10;\n\n    reg [1:0] state;\n    reg [11:0] candidate;\n\n    function automatic [3:0] compute_groups;\n        input [2:0] bits;\n        case (bits)\n            3'b000: compute_groups = {2'b00, 2'b00};\n            3'b001, 3'b010, 3'b100: compute_groups = {2'b01, 2'b00};\n            3'b011, 3'b110: compute_groups = {2'b10, 2'b00};\n            3'b101: compute_groups = {2'b01, 2'b01};\n            3'b111: compute_groups = {2'b11, 2'b00};\n            default: compute_groups = 4'd0;\n        endcase\n    endfunction\n\n    // Row checks\n    wire row0_check, row1_check;\n    assign row0_check = (compute_groups(candidate[2:0]) == {row0_g1, row0_g2});\n    assign row1_check = (compute_groups(candidate[5:3]) == {row1_g1, row1_g2});\n\n    // Column checks\n    wire col0_check, col1_check;\n    wire [2:0] H0_vec = {candidate[8], candidate[7], candidate[6]};\n    wire [2:0] H1_vec = {candidate[11], candidate[10], candidate[9]};\n    assign col0_check = (compute_groups(H0_vec) == {col0_g1, col0_g2});\n    assign col1_check = (compute_groups(H1_vec) == {col1_g1, col1_g2});\n\n    // Touch checks\n    wire touch_valid;\n    assign touch_valid =\n        ((candidate[0] + candidate[6]) <= 1'd1) &&\n        ((candidate[1] + candidate[6] + candidate[9]) <= 1'd1) &&\n        ((candidate[2] + candidate[9]) <= 1'd1) &&\n        ((candidate[0] + candidate[3] + candidate[7]) <= 1'd1) &&\n        ((candidate[1] + candidate[4] + candidate[7] + candidate[10]) <= 1'd1) &&\n        ((candidate[2] + candidate[5] + candidate[10]) <= 1'd1) &&\n        ((candidate[3] + candidate[8]) <= 1'd1) &&\n        ((candidate[4] + candidate[8] + candidate[11]) <= 1'd1) &&\n        ((candidate[5] + candidate[11]) <= 1'd1);\n\n    wire valid_candidate;\n    assign valid_candidate = row0_check && row1_check && col0_check && col1_check && touch_valid;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            candidate <= 12'd0;\n            done <= 1'b0;\n            row0_vbars <= 3'd0;\n            row1_vbars <= 3'd0;\n            col0_hbars <= 3'd0;\n            col1_hbars <= 3'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= SEARCH;\n                        candidate <= 12'd0;\n                    end\n                end\n                \n                SEARCH: begin\n                    if (valid_candidate) begin\n                        row0_vbars <= candidate[2:0];\n                        row1_vbars <= candidate[5:3];\n                        col0_hbars <= H0_vec;\n                        col1_hbars <= H1_vec;\n                        done <= 1'b1;\n                        state <= DONE_STATE;\n                    end else if (candidate == 12'd4095) begin\n                        done <= 1'b1;\n                        state <= DONE_STATE;\n                    end else begin\n                        candidate <= candidate + 12'd1;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    // Stay in DONE until reset\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule